"use client";
import React, { useRef } from "react";
import {
  Mail,
  Phone,
  MapPin,
  Clock,
  ArrowUp,
  BookOpen,
  Users,
  Award,
} from "lucide-react";

export default function Footer() {
  const scrollTopRef = useRef<HTMLButtonElement>(null);

  const handleScrollTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <footer className="relative overflow-hidden bg-slate-950 text-gray-100">
      <div className="absolute inset-0 top-40 opacity-50">
        <img
          src="/footerlayout.png"
          alt="Footer Background"
          className="object-cover w-full h-full"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/80 to-transparent" />
      </div>

      {/* Wavy decorative SVG separator */}
      <svg
        className="absolute top-0 left-0 w-full pointer-events-none"
        viewBox="0 0 1440 120"
        preserveAspectRatio="none"
        xmlns="http://www.w3.org/2000/svg"
        style={{ zIndex: 3 }}
      >
        <path
          d="M0,40 C240,120 480,0 720,40 C960,80 1200,0 1440,40 L1440,120 L0,120 Z"
          fill="rgb(2, 44, 52)"
        />
      </svg>

      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-12 pb-12 border-b border-cyan-500/20">
          <div className="space-y-4">
            <div className="flex items-center gap-2 mb-6">
              <BookOpen className="w-6 h-6 text-cyan-400" />
              <h3 className="text-xl font-bold text-white">About</h3>
            </div>
            <p className="text-sm text-gray-300 leading-relaxed">
              Empowering students with quality education and global opportunities for success.
            </p>
            <div className="flex gap-3 pt-2">
              <a
                href="mailto:info@edulink.com"
                className="p-2 bg-cyan-500/10 hover:bg-cyan-500/20 rounded-lg transition-all duration-300 hover:shadow-lg hover:shadow-cyan-500/20 transform hover:scale-105"
                aria-label="Email"
              >
                <Mail className="w-5 h-5 text-cyan-400" />
              </a>
              <a
                href="tel:+61123456789"
                className="p-2 bg-cyan-500/10 hover:bg-cyan-500/20 rounded-lg transition-all duration-300 hover:shadow-lg hover:shadow-cyan-500/20 transform hover:scale-105"
                aria-label="Phone"
              >
                <Phone className="w-5 h-5 text-cyan-400" />
              </a>
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center gap-2 mb-6">
              <Users className="w-6 h-6 text-cyan-400" />
              <h3 className="text-lg font-bold text-white">Quick Links</h3>
            </div>
            <ul className="space-y-3 text-sm">
              <li>
                <a
                  href="#"
                  className="text-gray-300 hover:text-cyan-400 transition-colors font-medium hover:translate-x-1"
                >
                  Our Programs
                </a>
              </li>
              <li>
                <a
                  href="#"
                  className="text-gray-300 hover:text-cyan-400 transition-colors font-medium hover:translate-x-1"
                >
                  About Us
                </a>
              </li>
              <li>
                <a
                  href="#"
                  className="text-gray-300 hover:text-cyan-400 transition-colors font-medium hover:translate-x-1"
                >
                  Success Stories
                </a>
              </li>
              <li>
                <a
                  href="#"
                  className="text-gray-300 hover:text-cyan-400 transition-colors font-medium hover:translate-x-1"
                >
                  Contact
                </a>
              </li>
            </ul>
          </div>

          <div className="space-y-4">
            <div className="flex items-center gap-2 mb-6">
              <Clock className="w-6 h-6 text-cyan-400" />
              <h3 className="text-lg font-bold text-white">Hours</h3>
            </div>
            <div className="space-y-3 text-sm">
              <div>
                <p className="font-semibold text-gray-200">Mon - Fri</p>
                <p className="text-gray-400">9:00 AM - 5:00 PM</p>
              </div>
              <div>
                <p className="font-semibold text-gray-200">Saturday</p>
                <p className="text-gray-400">9:00 AM - 1:00 PM</p>
              </div>
              <div>
                <p className="font-semibold text-gray-200">Sunday</p>
                <p className="text-gray-400">Closed</p>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center gap-2 mb-6">
              <MapPin className="w-6 h-6 text-cyan-400" />
              <h3 className="text-lg font-bold text-white">Location</h3>
            </div>
            <div className="space-y-3 text-sm">
              <div className="text-gray-300">
                <p className="font-semibold mb-1">Head Office</p>
                <p className="text-gray-400">
                  Level 5/12 Clarke St,
                  <br />
                  Sunshine, VIC 3020
                </p>
              </div>
              <a
                href="tel:+61123456789"
                className="text-cyan-400 hover:text-cyan-300 transition-colors font-medium block hover:underline"
              >
                +61 (0) 123 456 789
              </a>
              <a
                href="mailto:info@edulink.com"
                className="text-cyan-400 hover:text-cyan-300 transition-colors font-medium break-all hover:underline"
              >
                info@edulink.com
              </a>
            </div>
          </div>
        </div>

        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 pt-8">
          <p className="text-xs sm:text-sm text-gray-400">
            &copy; {new Date().getFullYear()} Edulink. All rights reserved.
            <a
              href="#"
              className="text-cyan-400 hover:text-cyan-300 ml-2 transition-colors hover:underline"
            >
              Privacy Policy
            </a>
          </p>

          <button
            ref={scrollTopRef}
            onClick={handleScrollTop}
            className="w-10 h-10 bg-gradient-to-r from-cyan-500 to-cyan-600 hover:from-cyan-400 hover:to-cyan-500 text-white rounded-full shadow-lg hover:shadow-xl hover:shadow-cyan-500/50 transition-all duration-300 flex items-center justify-center transform hover:scale-110"
            aria-label="Scroll to top"
          >
            <ArrowUp className="w-5 h-5" />
          </button>
        </div>
      </div>
    </footer>
  );
}
